import { criticalProgress, criticalDrillSummary } from './critical.mjs';
import { vnDate, profileValid, generatePaper, scorePaper, languagePolicy, phraseSegments, independent, reviewState, readiness, validateBackup, mergeBackups } from './engine.mjs';
import { openStore, readState, saveState, saveRollback, readRollback } from './storage.mjs';
const app=document.querySelector('#app'), modal=document.querySelector('#modal');
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(), now=()=>Date.now(), prettyDate=n=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Ho_Chi_Minh',day:'numeric',month:'short',year:'numeric'}).format(n), fold=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();
const chapterNames={1:'Road rules',2:'Culture & responsibility',3:'Riding technique',5:'Road signs',6:'Junctions & right of way'};
const levels=['Bilingual','English on request','Phrase help','Vietnamese only'];
const taxonomy={vocabulary:'Vocabulary / unknown phrase',negation:'Negation / qualifier',rule:'Traffic rule / concept',signs:'Similar road signs',diagram:'Junction / priority diagram',numbers:'Numbers / measurements',attention:'Attention / time pressure',unknown:'Not sure why yet'};
const icons={today:'◌',learn:'▤',review:'↻',test:'✓'};
function criticalTodayCard(){const c=criticalProgress(questions,state.attempts);return `<section class="card" aria-label="Critical question practice" style="margin-bottom:26px;border-top:3px solid #b99b42"><div class="card-head"><div><p class="eyebrow">CRITICAL QUESTIONS · CÂU HỎI ĐIỂM LIỆT</p><h2>One question can decide the whole test.</h2></div><span class="tag critical">${c.secure}/${c.total} SECURE</span></div><p>Each A/A1 mock contains exactly one of these ${c.total} questions. A wrong or blank critical answer fails, even at 24/25.</p><p class="source-note">${c.unseen} not yet attempted · ${c.total-c.secure} not independently secure · ${c.due} due for review</p><div class="actions">${button('critical','Open critical practice →','primary')}${button('critical-priority','Review what needs attention','secondary',c.priorityIds.length?'':'disabled')}${button('critical-drill','Check all 20 in Vietnamese','ghost')}</div></section>`;}
function criticalCollectionPanel(){const c=criticalProgress(questions,state.attempts);return `<section class="card" aria-label="Critical training overview" style="margin-bottom:24px"><p class="eyebrow">THE EXACT MOTORCYCLE LIST · A AND A1</p><h2>The 20 questions you cannot afford to miss.</h2><p>The official A/A1 bank contains ${c.total} critical questions. Every current-format mock draws exactly one. Wrong or unanswered means automatic failure, whatever your total score.</p><div class="stats" style="margin:22px 0">${[[c.unseen,'Not yet attempted'],[c.needsUnaided,'Needs unaided retrieval'],[c.developing,'Building spaced recall'],[c.secure,'Independently secure']].map(([n,label])=>`<div class="stat"><div class="stat-number">${n}</div><span class="stat-label">${label}</span></div>`).join('')}</div><div class="actions">${button('critical-priority','Practise questions needing attention','primary',c.priorityIds.length?'':'disabled')}${button('critical-drill','Start all-20 Vietnamese drill','secondary')}</div><p class="source-note">Targeted practice puts wrong or uncertain answers first, then unseen and due questions. The drill covers all 20 once, in a new order, with no English before each answer. It is a learning drill with feedback after every answer, not a mixed mock.</p><p class="source-note">“Secure” is our study target: three confident unaided successes on three Vietnam-local dates, including a gap of at least three days. One 20/20 drill is useful evidence but does not establish spaced mastery.</p><details><summary>Verify the official critical-question rule</summary><p>Guidance 2262/CSGT-P5: the A/A1 bank has 250 questions with 20 critical items; each current-format paper includes one critical question. Wrong or blank fails. The full 600-question bank for other categories has 60 critical items; only the motorcycle list applies here.</p><p><a href="https://xaydungchinhsach.chinhphu.vn/huong-dan-su-dung-bo-600-cau-hoi-dung-de-sat-hach-lai-xe-co-gioi-duong-bo-119250513110514585.htm" target="_blank" rel="noopener">Government guidance</a> · <a href="sources/official_guidance_2262.pdf#page=4" target="_blank" rel="noopener">Exact 20 IDs in Appendix I</a></p></details></section>`;}
function showCriticalDrillSummary(sessionId){const summary=criticalDrillSummary(questions,state.attempts,sessionId);openModal(`<p class="eyebrow">RECALL CHECK · NOT AN EXAM RESULT</p><h2>Critical drill complete</h2><p><strong>${summary.correct}/${summary.total} correct</strong> · ${summary.independentCorrect}/${summary.total} confident unaided answers.</p>${summary.needsReviewIds.length?`<p>Review questions ${summary.needsReviewIds.map(id=>byId.get(id).official_id).join(', ')}. Wrong answers and correct guesses stay in your review history.</p>`:'<p>Every critical question was answered correctly and confidently in Vietnamese in this session.</p>'}<p>Keep retrieving them on separate days. Today’s result does not make all 20 independently secure or count as a completed mixed mock.</p><div class="actions">${button('critical','See critical progress','primary')}${closeButton()}</div>`);}
function criticalResultRepair(exam){if(!exam.result?.criticalWrong)return '';const q=exam.ids.map(id=>byId.get(id)).find(q=>q.critical_for_motorcycle);if(!q)return '';return `<section class="notice" aria-label="Critical failure repair" style="margin-top:20px"><strong>The critical condition caused this failure.</strong><p>Question ${q.official_id} was ${exam.answers[q.id]?'answered incorrectly':'left unanswered'}. Even 24 correct answers cannot offset this. Review its rule and Vietnamese wording, then retrieve it again without help.</p><div class="actions">${button('repair-critical','Repair the critical question','primary',`data-id="${q.id}"`)}${button('critical','Open all 20 critical questions','secondary')}</div></section>`;}
let bank,questions,phrases,phraseData,profiles,byId,byPhrase,state,storageReady=false,storageError='',view='today',study=null,examId=null,examIndex=0,resultId=null,busy=false,search='',chapter='all',collection='all',reviewFilter='due',mistakeFilter='all',phraseIndex=0,phraseMode='flash',phraseRevealed=false,phraseAnswer=null,phraseChoices=[],phraseQueue=[],importCandidate=null,registration=null,offline={ready:false,done:0,total:0,error:''},installPrompt=null;
const fresh=()=>({schema_version:1,bank_version:bank.bank_id,preferences:{level:0,profileId:'vn-A-2025-06',dailyLimit:8,theme:'system'},attempts:[],exams:[],phraseAttempts:[],bookmarks:[],mistakeEdits:[]});
const profile=()=>profiles.find(p=>p.id===state.preferences.profileId)||profiles[0];
const activeExam=()=>state.exams.find(e=>e.id===examId&&e.status==='active');
const latest=(id)=>state.attempts.filter(a=>a.questionId===id).sort((a,b)=>a.at-b.at).at(-1);
const history=id=>state.attempts.filter(a=>a.questionId===id);
const qState=id=>reviewState(history(id));
const tagsFor=a=>state.mistakeEdits.filter(e=>e.attemptId===a.id).sort((a,b)=>a.at-b.at).at(-1)?.mistakes??a.mistakes??[];
function toast(message){const node=document.querySelector('#toast');node.textContent=message;node.style.cssText='position:fixed;bottom:100px;left:50%;transform:translateX(-50%);z-index:1000;max-width:calc(100% - 30px);padding:12px 18px;border-radius:10px;background:#243b31;color:white;font-size:13px;box-shadow:0 8px 35px #0003';clearTimeout(toast.timer);toast.timer=setTimeout(()=>{node.textContent='';node.style.cssText='';},4500);}
async function persist(next){if(!storageReady){state=next;toast('Practice is temporary: browser storage is unavailable. Export a backup before leaving.');return;}try{await saveState(next);state=next;storageError='';}catch(error){storageError=error.message;throw Error('Progress could not be saved. Your previous saved record is intact. '+error.message);}}
async function change(fn){const next=structuredClone(state);fn(next);await persist(next);}
function button(action,label,kind='secondary',extra=''){return `<button class="button ${kind}" data-action="${action}" ${extra}>${label}</button>`;}
function openModal(html){modal.innerHTML=`<div class="modal-body">${html}</div>`;if(!modal.open)modal.showModal();}
const closeButton=()=>button('close-modal','Close','ghost');
function applyTheme(){document.body.dataset.theme=state.preferences.theme;}
function setView(next){const running=state.exams.find(e=>e.status==='active');if(running&&next!=='test'){view='test';examId=running.id;study=null;resultId=null;render();toast('Finish or abandon the active paper before opening study aids.');return;}if(next==='review'){collection='all';search='';}view=next;study=null;resultId=null;if(next!=='test')examId=null;render();window.scrollTo(0,0);}
function offlineLabel(){return offline.ready?'Ready offline':offline.error?'Offline download incomplete':offline.total?`Preparing offline · ${offline.done}/${offline.total}`:'Preparing offline';}
function shell(body){const nav=['today','learn','review','test'].map(t=>`<button class="nav-link ${view===t?'active':''}" data-action="nav" data-view="${t}" aria-current="${view===t?'page':'false'}"><span class="nav-icon" aria-hidden="true">${icons[t]}</span><span>${t[0].toUpperCase()+t.slice(1)}</span></button>`).join('');return `<div class="shell"><aside class="sidebar"><a class="brand" href="#today" data-action="nav" data-view="today"><span class="brand-dot">đ</span><span>đường<span class="brand-caption">Motorcycle theory, understood</span></span></a><nav aria-label="Main navigation">${nav}</nav><div class="sidebar-foot"><p class="eyebrow">ONE ROAD. A LITTLE CLEARER.</p><p>Learn the language.<br>Understand the rules.<br>Ride with confidence.</p><div class="divider"></div><button class="button ghost small" data-action="settings">Settings & backups</button><button class="button ghost small" data-action="about">About the question bank</button><p id="offline-label">${escape(offlineLabel())}</p></div></aside><main class="main"><header class="topbar"><span>${escape(prettyDate(now()))}<span class="desktop-only"> · YOUR OWN PACE, EVERY DAY</span></span><div class="row"><span class="tag">LICENCE ${escape(profile().licence_category)}</span><button class="button ghost small" data-action="settings" aria-label="Settings and backups">⚙ <span class="desktop-only">Settings</span></button></div></header>${!storageReady?`<div class="notice" role="alert"><strong>Progress is not saved on this browser.</strong> ${escape(storageError)} You can practice and export a backup, but timed mocks require working storage.</div>`:''}${storageReady&&storageError?`<div class="error" role="alert">${escape(storageError)}</div>`:''}${!profileValid(profile())?`<div class="notice"><strong>Archived study bank.</strong> This format was verified through 28 February 2027. Current-exam mocks are disabled until a new bank and profile are verified.</div>`:''}${body}<p class="footer-note">Your progress stays on this browser. Export a backup to keep a copy. <button class="link" data-action="about">Content & sources</button></p></main></div>`;}
function render(){if(!state)return;applyTheme();let body=study?studyView():view==='today'?todayView():view==='learn'?learnView():view==='review'?reviewView():view==='phrases'?phraseView():testView();app.innerHTML=shell(body);updateTimer();}
const roadArt=`<svg viewBox="0 0 260 230" fill="none" aria-hidden="true"><circle cx="137" cy="112" r="95" stroke="#95b49d" stroke-opacity=".2"/><circle cx="137" cy="112" r="64" stroke="#95b49d" stroke-opacity=".2"/><path d="M35 234C10 171 212 198 191 131C169 65 80 109 83 39C84 15 108 0 115-17" stroke="#377061" stroke-width="48"/><path d="M35 234C10 171 212 198 191 131C169 65 80 109 83 39C84 15 108 0 115-17" stroke="#d2b76b" stroke-width="2" stroke-dasharray="9 10"/><circle cx="191" cy="133" r="11" fill="#d2b76b"/><circle cx="191" cy="133" r="4" fill="#174f43"/><path d="M213 51v29m-14-14h29" stroke="#d2b76b" stroke-width="2"/><circle cx="42" cy="91" r="4" fill="#d2b76b" opacity=".7"/><path d="M89 184h18m-9-9v18" stroke="#a8c0aa"/></svg>`;
function todayView(){const r=readiness(questions,state.attempts,state.exams),date=vnDate(),firstIds=new Set();for(const a of [...state.attempts].sort((a,b)=>a.at-b.at))if(!firstIds.has(a.questionId))firstIds.add(a.questionId);const todayAttempts=state.attempts.filter(a=>vnDate(a.at)===date).length;return `<div class="page-head"><div><p class="eyebrow">A LITTLE PRACTICE. A CLEARER ROAD.</p><h1>Your next step starts here.</h1><p>Build your Vietnamese, one real question at a time.</p></div><span class="tag">${todayAttempts} attempts today</span></div><section class="hero"><div class="hero-copy"><p class="eyebrow">TODAY’S PRACTICE</p><h2>Learn the language.<br>Know the way.</h2><p>Authentic questions. English when you need it.<br>A little less help when you’re ready.</p><div class="actions">${button('daily-learn','Continue learning &nbsp; →','primary')}${button('phrases','Practise Vietnamese','ghost')}</div></div><div class="hero-art">${roadArt}</div></section><section class="stats" aria-label="Learning progress">${[[r.coverage,'/250','Questions attempted'],[r.mastered,'/250','Independently mastered'],[r.criticalMastered,'/20','Critical questions secure'],[r.due,'','Reviews due']].map(([n,out,label])=>`<div class="stat"><div class="stat-number">${n}<small>${out}</small></div><span class="stat-label">${label}</span></div>`).join('')}</section>${criticalTodayCard()}<div class="grid-two"><section class="card"><div class="card-head"><h2>A manageable daily plan</h2><span class="tag">15–20 MIN</span></div>${[[1,'New ground',`Learn up to ${state.preferences.dailyLimit} new questions.`, 'daily-learn','Learn'],[2,'Keep it fresh',r.due?`${r.due} questions ready to revisit.`:'Your due reviews will appear here.','due-review','Review'],[3,'Read with confidence','Build the phrases the test uses.','phrases','Phrases']].map(([n,title,desc,action,label])=>`<div class="plan-row"><span class="plan-step">${n}</span><div><h3>${title}</h3><p>${desc}</p></div>${button(action,label,'secondary small')}</div>`).join('')}</section><section class="card"><p class="eyebrow">CONFIDENCE COMES FROM EVIDENCE</p><h2>Seen is a start.<br>Understood takes practice.</h2><p class="muted" style="font-size:13px">Independent mastery means correct, confident Vietnamese-only answers across three separate days, including a gap of at least three days.</p><div class="progress-track"><div class="progress-fill" style="width:${r.mastered/250*100}%"></div></div><p class="source-note">${r.mastered} independently mastered · ${r.revisited} revisited on another day</p>${button('readiness','See your readiness evidence','ghost small')}</section></div><div class="section-head"><h2>Choose your next stretch</h2>${button('browse','Explore all 250','ghost small')}</div><section class="topic-grid">${[[1,'Road rules','100 authentic questions','↗'],[5,'Road signs','90 signs to understand','△'],[6,'Right of way','35 junction questions','⇄']].map(([c,title,desc,icon])=>`<button class="topic-card" data-action="chapter" data-chapter="${c}"><span class="topic-icon">${icon}</span><h3>${title}</h3><p>${desc}</p></button>`).join('')}</section><div class="notice"><strong>Critical questions deserve extra care.</strong> One wrong or unanswered critical question fails a mock, whatever the total score. ${button('critical','Practise the exact 20','ghost small')}</div>`;}
function filteredQuestions(isReview=false){let list=questions.filter(q=>chapter==='all'||q.chapter===Number(chapter));if(search){const s=fold(search).trim();list=list.filter(q=>String(q.official_id)===s||fold(`${q.question.vi} ${q.question.en??''} ${q.options.map(o=>o.text.vi+' '+(o.text.en??'')).join(' ')}`).includes(s));}if(collection==='critical')list=list.filter(q=>q.critical_for_motorcycle);if(collection==='saved')list=list.filter(q=>state.bookmarks.includes(q.id));if(isReview){list=list.filter(q=>{const a=latest(q.id),r=qState(q.id);if(reviewFilter==='critical')return q.critical_for_motorcycle&&!r.mastered;if(reviewFilter==='saved')return state.bookmarks.includes(q.id);if(!a)return false;if(reviewFilter==='due')return r.due<=now();if(reviewFilter==='mistakes')return r.unresolved||!a.correct;if(reviewFilter==='unsure')return a.confidence!=='sure';if(reviewFilter==='assisted')return a.correct&&!independent(a);return true;});if(mistakeFilter!=='all')list=list.filter(q=>history(q.id).some(a=>tagsFor(a).includes(mistakeFilter)&&qState(q.id).unresolved));}return list;}
function chapterSelect(){return `<div class="field"><label for="chapter-select">Topic</label><select id="chapter-select" data-change="chapter"><option value="all">All topics</option>${Object.entries(chapterNames).map(([id,title])=>`<option value="${id}" ${chapter===id?'selected':''}>${escape(title)}</option>`).join('')}</select></div>`;}
function supportSelect(){return `<div class="field"><label for="support-select">English support</label><select id="support-select" data-change="support">${levels.map((name,n)=>`<option value="${n}" ${state.preferences.level===n?'selected':''}>${n} · ${name}</option>`).join('')}</select></div>`;}
function bankRows(list){return list.length?`<div class="bank-list">${list.map(q=>{const a=latest(q.id);return `<button class="bank-item" data-action="single" data-id="${q.id}"><span>${q.official_id}</span><div style="flex:1;min-width:0"><p lang="vi">${escape(q.question.vi)}</p><small>${escape(chapterNames[q.chapter])}${a?` · ${qState(q.id).mastered?'Independently secure':!a.correct?'Needs another try':a.confidence!=='sure'?'Revisit with confidence':independent(a)?'Independent retrieval':'Assisted practice'}`:' · Not yet attempted'}</small></div>${q.critical_for_motorcycle?'<span class="tag critical">CRITICAL</span>':''}${state.bookmarks.includes(q.id)?'<span aria-label="Saved">☆</span>':''}<span aria-hidden="true">→</span></button>`;}).join('')}</div>`:'<div class="empty"><h3>No questions here yet.</h3><p>Try another filter or topic.</p></div>';}
function learnView(){const list=filteredQuestions();return `<div class="page-head"><div><p class="eyebrow">LEARN AT YOUR OWN PACE</p><h1>Understand, then remember.</h1><p>All 250 original questions. Choose the support that helps you move forward.</p></div>${button('phrases','Vietnamese phrase course','secondary')}</div><div class="chips">${[['all','Full bank · 250'],['critical','Critical · 20'],['saved',`Saved · ${state.bookmarks.length}`]].map(([id,name])=>`<button class="chip ${collection===id?'active':''}" data-action="collection" data-value="${id}">${name}</button>`).join('')}</div>${collection==='critical'?criticalCollectionPanel():''}<div class="toolbar"><div class="field" style="flex:2"><label for="search">Search question number, Vietnamese or English</label><input id="search" type="search" value="${escape(search)}" placeholder="Try 362, nhường đường, or priority" data-input="search"></div>${chapterSelect()}${supportSelect()}</div><div class="row between" style="flex-wrap:wrap;margin:18px 0"><span class="muted">${list.length} questions</span><div class="actions">${button('selected-ids','Choose question numbers','ghost small')}${button('study-list','Study this selection →','primary',list.length?'':'disabled')}</div></div>${bankRows(list)}`;}
function reviewView(){const list=filteredQuestions(true);return `<div class="page-head"><div><p class="eyebrow">MAKE IT STICK</p><h1>A second look, a stronger grasp.</h1><p>Revisit the question and the reason it was difficult. A confident unaided retrieval repairs an earlier mistake.</p></div></div><div class="chips">${[['due','Due'],['mistakes','Mistakes'],['unsure','Guessed / unsure'],['assisted','Assisted correct'],['critical','Critical'],['saved','Saved']].map(([id,name])=>`<button class="chip ${reviewFilter===id?'active':''}" data-action="review-filter" data-value="${id}">${name}</button>`).join('')}</div><div class="toolbar">${chapterSelect()}<div class="field"><label for="mistake-select">Mistake reason</label><select id="mistake-select" data-change="mistake"><option value="all">All reasons</option>${Object.entries(taxonomy).map(([id,name])=>`<option value="${id}" ${mistakeFilter===id?'selected':''}>${escape(name)}</option>`).join('')}</select></div>${supportSelect()}${button('review-list',`Review ${list.length} questions →`,'primary',list.length?'':'disabled')}</div>${bankRows(list)}`;}
function phraseText(text,policy){return policy.phrases?phraseSegments(text,phrases).map(s=>s.phrase?`<button class="phrase-help" data-action="phrase-help" data-id="${escape(s.phrase.id)}" lang="vi">${escape(s.text)}</button>`:escape(s.text)).join(''):escape(text);}
function figures(q,strict=false){return q.images.length?`<div class="figures">${q.images.map((im,i)=>`<figure class="figure"><button class="button ghost" style="padding:0;background:white;display:block;margin:auto" data-action="zoom" data-id="${q.id}" data-index="${i}" aria-label="${escape(strict?im.alt_vi:'Enlarge '+im.alt_en)}"><img src="${escape(im.path)}" alt="${escape(strict?im.alt_vi:im.alt_en)}" width="${im.width}" height="${im.height}" data-question-image="${q.id}"></button>${im.figure_label?`<figcaption lang="vi">Hình ${escape(im.figure_label)}</figcaption>`:''}</figure>`).join('')}</div>`:'';}
function textBlock(q,field,vi,en,policy,ctx){const showEn=ctx.examFinished||(ctx.committed&&ctx.level<3)||ctx.reveals?.has('review')||ctx.level===0||ctx.reveals?.has(field);const allowed=policy.english||policy.englishOnRequest;return `<div lang="vi">${phraseText(vi,policy)}</div>${showEn&&allowed?`<div class="translation" lang="en">${escape(en??'English content unavailable for this item.')}</div>`:policy.englishOnRequest&&ctx.level===1?`<button class="button ghost small" data-action="reveal" data-field="${escape(field)}">Reveal English</button>`:''}`;}
function questionContent(q,ctx){const policy=languagePolicy(ctx.level,ctx.committed,ctx.examFinished),showFeedback=policy.feedback;return `<div class="question-top"><div class="row"><span>QUESTION ${q.official_id}</span>${policy.critical&&q.critical_for_motorcycle?'<span class="tag critical">CRITICAL</span>':''}<span>${escape(chapterNames[q.chapter])}</span></div>${ctx.level!==4?`<button class="button ghost small" data-action="bookmark" data-id="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'Remove bookmark':'Save question'}">${state.bookmarks.includes(q.id)?'★ Saved':'☆ Save'}</button>`:''}</div><div class="question-text">${textBlock(q,'question',q.question.vi,q.question.en,policy,ctx)}</div>${figures(q,policy.strict)}<div class="options" role="group" aria-label="Answer options">${q.options.map(o=>{const selected=ctx.answerId===o.id,correct=showFeedback&&o.id===q.correct_option_id,wrong=showFeedback&&selected&&!correct;return `<div class="option ${selected?'selected':''} ${correct?'correct':''} ${wrong?'incorrect':''}" ${ctx.committed||ctx.examFinished?'':`data-action="answer" data-id="${o.id}" role="button" tabindex="0" aria-pressed="${selected}"`}><span class="option-number">${o.number}</span><div class="option-body">${textBlock(q,o.id,o.text.vi,o.text.en,policy,ctx)}</div>${correct?'<span aria-label="Correct answer">✓</span>':wrong?'<span aria-label="Your incorrect answer">×</span>':''}</div>`;}).join('')}</div>${showFeedback?feedback(q,ctx):''}`;}
function feedback(q,ctx){const correct=ctx.answerId===q.correct_option_id,english=ctx.examFinished||ctx.level<3||ctx.reveals?.has('review');return `<section class="feedback ${correct?'good':'bad'}"><h3>${correct?'Correct. Keep building on it.':ctx.answerId?'A useful question to revisit.':'This question was unanswered.'}</h3><p>Official answer: <strong>${q.correct_option_number}</strong> <span lang="vi">${escape(q.options.find(o=>o.id===q.correct_option_id).text.vi)}</span></p>${ctx.level===3&&!english?button('review-english','Reveal English review','secondary small'):''}${english?`<p>${escape(q.explanation?.en??'Use the official keyed choice above and the source reference to review this question.')}</p>${q.image_glosses_en?.length?`<p class="muted">${escape(q.image_glosses_en.map(x=>typeof x==='string'?x:x.en??x.text??'').join(' · '))}</p>`:''}${q.language_chunks?.length?`<p class="source-note">${q.language_chunks.map(c=>`<span lang="vi">${escape(c.vi)}</span> = ${escape(c.en)}`).join(' · ')}</p>`:''}`:''}${ctx.level!==4&&(!correct||ctx.confidence!=='sure')?`<p class="source-note">${correct?'A correct guess still deserves another retrieval.':'Name what made this difficult. These are your choices, not an automatic diagnosis.'}</p>${reasonGrid(ctx.attemptId)}`:''}<p class="source-note">Official source · PDF page ${q.source.pdf_pages_1_based.join(', ')} · <a href="${escape(q.source.pdf_path)}#page=${q.source.pdf_pages_1_based[0]}" target="_blank" rel="noopener">Open source after answering</a><br>English is AI-authored learning support, not an official translation.</p>${q.source_caution?`<p class="notice">Source wording note: ${escape(q.source_caution)}</p>`:''}${ctx.level!==4?`<div class="actions">${button('repair-phrases','Repair with linked phrases','ghost small',`data-id="${q.id}"`)}${button('single','Try later with less help','ghost small',`data-id="${q.id}" data-level="3"`)}</div>`:''}</section>`;}
function reasonGrid(attemptId){const a=state.attempts.find(a=>a.id===attemptId);if(!a)return '';const tags=tagsFor(a);return `<div class="reason-grid">${Object.entries(taxonomy).map(([id,label])=>`<label><input type="checkbox" data-change="reason" data-attempt="${a.id}" value="${id}" ${tags.includes(id)?'checked':''}>${label}</label>`).join('')}</div>`;}
function startStudy(ids,level=state.preferences.level,mode=view==='review'?'review':'learn'){const running=state.exams.find(e=>e.status==='active');if(running){view='test';examId=running.id;study=null;render();toast('Finish or abandon your active paper before starting study.');return;}if(!ids.length){toast('No questions match this selection.');return;}study={ids:[...ids],index:0,level,mode,sessionId:uid(),answerId:null,committed:false,confidence:'sure',reveals:new Set(),support:[],startedAt:now(),attemptId:null,retried:new Set()};render();window.scrollTo(0,0);}
function studyView(){const q=byId.get(study.ids[study.index]);return `<div class="page-head"><div><p class="eyebrow">${study.mode==='critical-drill'?'ALL 20 MOTORCYCLE CRITICAL QUESTIONS':study.mode==='review'?'RETRIEVE & REPAIR':'LEARN & UNDERSTAND'}</p><h1>${study.mode==='critical-drill'?'Critical questions · Vietnamese-only drill':levels[study.level]+' practice'}</h1><p>${study.index+1} of ${study.ids.length} · ${study.mode==='critical-drill'?'Learning drill, not a mock. Feedback appears after each committed answer.':'Original choices stay in their original order.'}</p></div>${button('end-study','Back to collection','ghost')}</div><div class="question-shell"><div class="row between" style="margin-bottom:15px"><span class="tag">SUPPORT LEVEL ${study.level}</span>${study.mode==='critical-drill'?'<span class="source-note">Vietnamese only before each answer</span>':button('change-support','Adjust English support','ghost small')}</div><section class="question-card">${questionContent(q,{...study,examFinished:false})}${!study.committed?`<div class="confidence"><span>How does your answer feel?</span>${['sure','unsure','guessed'].map(c=>`<button class="chip ${study.confidence===c?'active':''}" data-action="confidence" data-value="${c}">${c[0].toUpperCase()+c.slice(1)}</button>`).join('')}</div><div class="actions">${button('commit','Check answer','primary',study.answerId?'':'disabled')}</div>`:`<div class="actions">${button('next-study',study.index+1<study.ids.length?'Next question →':'Finish this session','primary')}</div>`}</section><p class="source-note">${study.level>=3?'Unaided reading: English help and speech are unavailable before your answer is committed.':'Any English or phrase help is recorded. Only confident level 3–4 responses count toward independent mastery.'}</p></div>`;}
function dailyLearn(){const seen=new Set(state.attempts.map(a=>a.questionId));const first=new Map();for(const a of state.attempts)if(!first.has(a.questionId)||a.at<first.get(a.questionId).at)first.set(a.questionId,a);const newToday=[...first.values()].filter(a=>vnDate(a.at)===vnDate()).length;const remaining=Math.max(0,state.preferences.dailyLimit-newToday);const ids=questions.filter(q=>!seen.has(q.id)).slice(0,remaining).map(q=>q.id);if(!ids.length){toast(seen.size===250?'You have attempted the whole bank. Continue with review.':'Your new-question target is complete today. Revisit something you have learned.');view='review';reviewFilter='due';render();return;}view='learn';startStudy(ids);}
async function commitStudy(){if(!study||study.committed||!study.answerId)return;const q=byId.get(study.ids[study.index]);if(q.content_error)throw Error('This question needs its source diagram. Reload or retry offline preparation before answering.');const at=now(),event={id:uid(),questionId:q.id,answerId:study.answerId,correct:study.answerId===q.correct_option_id,at,startedAt:study.startedAt,level:study.level,support:structuredClone(study.support),confidence:study.confidence,mistakes:[],taxonomy_version:1,sessionId:study.sessionId,mode:study.mode};await change(s=>s.attempts.push(event));study.committed=true;study.attemptId=event.id;if(study.mode!=='critical-drill'&&(!event.correct||event.confidence!=='sure')&&!study.retried.has(q.id)&&study.ids.length-study.index-1>=3){study.ids.splice(study.index+4,0,q.id);study.retried.add(q.id);}render();}
function setupPhraseQueue(ids=null){phraseQueue=(ids?phrases.filter(p=>ids.includes(p.id)):phrases).sort((a,b)=>{const due=p=>{const a=state.phraseAttempts.filter(x=>x.phraseId===p.id).at(-1);return a?a.at+(a.intervalDays??1)*86400000:0;};return due(a)-due(b)||(a.initial_priority??5)-(b.initial_priority??5);}).map(p=>p.id);phraseIndex=0;resetPhrase();}
function resetPhrase(){phraseRevealed=false;phraseAnswer=null;const p=byPhrase.get(phraseQueue[phraseIndex]);if(p){const contrasting=(p.contrast_ids??[]).map(id=>byPhrase.get(id)).filter(Boolean);const alternate=contrasting[0]||phrases.find(x=>x.id!==p.id&&x.group===p.group)||phrases.find(x=>x.id!==p.id);phraseChoices=[p,alternate].sort(()=>Math.random()-.5);}}
function phraseView(){if(!phraseQueue.length)setupPhraseQueue();const p=byPhrase.get(phraseQueue[phraseIndex]);if(!p)return '<div class="empty"><h2>Phrase practice complete.</h2></div>';const due=phrases.filter(p=>{const a=state.phraseAttempts.filter(x=>x.phraseId===p.id).at(-1);return a&&a.at+(a.intervalDays??1)*86400000<=now();}).length;const occurrence=p.occurrences?.[0],linked=occurrence?byId.get(occurrence.question_id):null;let sourceText=linked?.question.vi??'';if(linked&&occurrence.field.startsWith('options.')){const optionId=occurrence.field.split('.')[1];sourceText=linked.options.find(o=>o.id===optionId)?.text.vi??sourceText;}const content=phraseMode==='contrast'?`<p class="eyebrow">WHICH VIETNAMESE PHRASE MEANS THIS?</p><div class="phrase-meaning">${escape(p.en)}</div><div class="actions" style="justify-content:center">${phraseChoices.map(x=>button('phrase-answer',escape(x.vi),phraseAnswer&&x.id===p.id?'primary':'secondary',`data-id="${x.id}" ${phraseAnswer?'disabled':''}`)).join('')}</div>${phraseAnswer?`<p class="source-note">${phraseAnswer===p.id?'Correct.':'The matching phrase is '+escape(p.vi)+'.'} ${escape(p.reading_note_en)}</p>`:''}`:phraseMode==='locate'?`<p class="eyebrow">FIND IT IN AN AUTHENTIC QUESTION</p><div class="phrase-word" lang="vi">${escape(p.vi)}</div>${linked?`<p class="question-text" style="font-size:19px;font-weight:400" lang="vi">${phraseSegments(sourceText,[p]).map(s=>s.phrase?`<mark class="phrase-hit">${escape(s.text)}</mark>`:escape(s.text)).join('')}</p><p class="source-note">From question ${linked.official_id}. This excerpt does not identify the correct answer.</p>`:'<p class="muted">Use the linked question collection to practise this phrase.</p>'}${phraseRevealed?`<div class="phrase-meaning">${escape(p.en)}</div><p class="muted">${escape(p.reading_note_en)}</p>`:button('phrase-reveal','Reveal the meaning','primary')}`:`<p class="eyebrow">READ THE PHRASE, THEN RECALL ITS MEANING</p><div class="phrase-word" lang="vi">${escape(p.vi)}</div>${phraseRevealed?`<div class="phrase-meaning">${escape(p.en)}</div><p class="muted">${escape(p.reading_note_en)}</p>`:button('phrase-reveal','Reveal the meaning','primary')}`;return `<div class="page-head"><div><p class="eyebrow">THE LANGUAGE OF THE TEST</p><h1>Small phrases. Big differences.</h1><p>${phrases.length} useful chunks · ${due} due for another look</p></div>${button('browse','Back to question bank','ghost')}</div><div class="chips">${[['flash','Read & recall'],['contrast','Choose the meaning'],['locate','Find in a question']].map(([id,name])=>`<button class="chip ${phraseMode===id?'active':''}" data-action="phrase-mode" data-value="${id}">${name}</button>`).join('')}</div><section class="phrase-card">${content}${p.ambiguous_without_context?'<p class="source-note">This phrase needs context. Its meaning cannot safely be guessed from an isolated word.</p>':''}${speechVoice()?button('phrase-speak','Listen in Vietnamese','ghost small'):''}</section><div class="actions" style="justify-content:center">${phraseMode==='contrast'?(phraseAnswer?button('phrase-next','Next phrase →','primary'):''):phraseRevealed?`${button('phrase-rate','Needs another look','secondary','data-value="false"')}${button('phrase-rate','I recalled it','primary','data-value="true"')}`:''}</div><p class="source-note" style="text-align:center">Phrase ${phraseIndex+1} of ${phraseQueue.length} · Reading practice, not a spelling test.</p>${linked?`<div class="card" style="margin-top:25px"><div class="row between" style="flex-wrap:wrap"><div><h3>Put the phrase to work.</h3><p class="muted">Return to an authentic question with less English help.</p></div>${button('single','Practise question '+linked.official_id,'secondary',`data-id="${linked.id}" data-level="2"`)}</div></div>`:''}`;}
function speechVoice(){return window.speechSynthesis?.getVoices().find(v=>v.lang.toLowerCase().startsWith('vi'));}
async function recordPhrase(correct){const p=byPhrase.get(phraseQueue[phraseIndex]),past=state.phraseAttempts.filter(a=>a.phraseId===p.id),a={id:uid(),phraseId:p.id,at:now(),correct,activity:phraseMode,intervalDays:correct?Math.min(30,[1,3,7,14,30][Math.min(past.filter(x=>x.correct).length,4)]):1};await change(s=>s.phraseAttempts.push(a));}
function testView(){const p=profile(),e=activeExam(),result=resultId?state.exams.find(x=>x.id===resultId):null;if(e)return examView(e);if(result)return resultsView(result);const current=state.exams.find(e=>e.status==='active');const exams=[...state.exams].sort((a,b)=>b.startedAt-a.startedAt);return `<div class="page-head"><div><p class="eyebrow">PUT YOUR READING TO THE TEST</p><h1>A clear picture of your progress.</h1><p>Original Vietnamese. No hints during the paper. A full review when you finish.</p></div></div>${current?`<div class="notice"><strong>A paper is in progress.</strong> Its clock continues in the background.<div class="actions" style="margin-top:12px">${button('resume-exam','Resume saved paper','primary',`data-id="${current.id}"`)}${button('abandon-exam','Abandon this paper','ghost',`data-id="${current.id}"`)}</div></div>`:''}<div class="grid-two"><section class="card"><p class="eyebrow">AUTHENTIC FORMAT · LICENCE ${p.licence_category}</p><h2>A strict timed mock</h2><div class="row" style="gap:23px;margin:23px 0"><div><div class="stat-number">25</div><small class="muted">questions</small></div><div><div class="stat-number">19</div><small class="muted">minutes</small></div><div><div class="stat-number">${p.minimum_correct}</div><small class="muted">to pass</small></div></div><p class="muted">Exactly one critical question. A wrong or blank critical answer fails the paper. No English, hints or answer feedback before final submission.</p>${button('start-exam','Start a timed mock →','primary',!profileValid(p)||!storageReady||current?'disabled':'')}<p class="source-note">Current profile valid through 28 February 2027, Vietnam time. Reloading never resets the paper or clock.</p></section><section class="card"><p class="eyebrow">BUILD FAMILIARITY</p><h2>An untimed practice paper</h2><p class="muted">The same 25-question mix and Vietnamese-only experience, with time to think. The result is marked as untimed practice and does not count toward your strict-mock evidence.</p>${button('start-practice','Start untimed practice','secondary',!profileValid(p)||!storageReady||current?'disabled':'')}<div class="divider"></div><p class="source-note">All answer choices retain their official order. Both papers save after every selection.</p></section></div><section class="card"><div class="card-head"><h2>Your paper history</h2>${button('readiness','Readiness evidence','ghost small')}</div>${exams.length?`<div class="bank-list">${exams.map(e=>`<button class="bank-item" data-action="${e.status==='active'?'resume-exam':'exam-result'}" data-id="${e.id}"><div><strong>${e.timed===false?'Untimed practice':'Strict timed mock'} · ${escape(e.profileId.includes('A1')?'A1':'A')}</strong><p class="source-note">${escape(prettyDate(e.startedAt))} · ${e.status==='abandoned'?'Abandoned — not a pass':e.status==='active'?'In progress':e.result.passed?'Passed':'Not passed'}</p></div><span class="stat-number" style="font-size:24px">${e.result?e.result.correct+'/25':'—'}</span></button>`).join('')}</div>`:'<p class="muted">Your completed and abandoned papers will appear here.</p>'}</section>`;}
async function verifyFigures(){if(offline.ready)return questions;toast('Checking source diagrams before preparing the paper…');const images=questions.flatMap(q=>q.images.map(im=>({q,im}))),bad=new Set();let cursor=0;await Promise.all(Array.from({length:4},async()=>{while(cursor<images.length){const {q,im}=images[cursor++];try{const response=await fetch(im.path);if(!response.ok)throw Error('Missing diagram');const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await response.arrayBuffer()))].map(b=>b.toString(16).padStart(2,'0')).join('');if(hash!==im.sha256)throw Error('Diagram checksum differs');}catch{bad.add(q.id);}}}));if(bad.size)toast(`${bad.size} questions have unavailable diagrams and are excluded from this paper.`);return questions.map(q=>bad.has(q.id)?{...q,unavailable:true}:q);}
async function startExam(timed){if(!storageReady)throw Error('Browser storage must work before a timed or saved paper can start.');if(!profileValid(profile()))throw Error('This profile has expired. Archived learning remains available.');if(state.exams.some(e=>e.status==='active'))throw Error('Resume or abandon your existing paper first.');const eligible=await verifyFigures(),paper=generatePaper(eligible,profile(),uid()),startedAt=now(),exam={id:uid(),ids:paper.ids,seed:paper.seed,answers:{},startedAt,deadline:timed?startedAt+profile().duration_seconds*1000:Number.MAX_SAFE_INTEGER,profileId:profile().id,bankVersion:bank.bank_id,status:'active',timed,level:4,mode:timed?'exam':'practice'};await change(s=>s.exams.push(exam));examId=exam.id;examIndex=0;resultId=null;view='test';study=null;render();window.scrollTo(0,0);}
function examView(e){const q=byId.get(e.ids[examIndex]),answered=Object.values(e.answers).filter(Boolean).length;return `<div class="page-head"><div><p class="eyebrow">${e.timed===false?'UNTIMED PRACTICE':'STRICT TIMED MOCK'} · VIETNAMESE ONLY</p><h1>One question at a time.</h1><p>${answered} of 25 answered · Your selections are saved.</p></div>${button('abandon-exam','Abandon paper','ghost small',`data-id="${e.id}"`)}</div><div class="exam-layout"><div class="question-shell"><section class="question-card">${questionContent(q,{level:4,committed:false,examFinished:false,answerId:e.answers[q.id],reveals:new Set()})}<div class="actions between">${button('exam-prev','← Previous','secondary',examIndex===0?'disabled':'')}${button('exam-next',examIndex===24?'Review navigator':'Next →','primary',examIndex===24?'disabled':'')}</div></section></div><aside class="exam-nav"><h3>${e.timed===false?'No time limit':'Time remaining'}</h3><div class="timer" data-timer>${timerText(e)}</div><p>${answered}/25 answered</p><div class="question-numbers">${e.ids.map((id,i)=>`<button class="number ${i===examIndex?'current':''} ${e.answers[id]?'answered':''}" data-action="exam-go" data-index="${i}" aria-label="Question ${i+1}${e.answers[id]?', answered':''}" aria-current="${i===examIndex?'step':'false'}">${i+1}</button>`).join('')}</div>${button('submit-exam','Submit whole paper','primary')}<p class="source-note">Background time counts. Answers can be changed until submission.</p></aside></div>`;}
function timerText(e){if(e.timed===false)return 'Untimed';const seconds=Math.max(0,Math.ceil((e.deadline-now())/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function updateTimer(){const e=activeExam();if(e)for(const el of document.querySelectorAll('[data-timer]')){el.textContent=timerText(e);el.classList.toggle('urgent',e.timed!==false&&e.deadline-now()<120000);}}
async function finishExam(id,expired=false){const old=state.exams.find(e=>e.id===id);if(!old||old.status!=='active')return;const p=profiles.find(p=>p.id===old.profileId),finishedAt=old.timed===false?now():Math.min(now(),old.deadline),result=scorePaper(questions,p,old.ids,old.answers);await change(s=>{const e=s.exams.find(x=>x.id===id);if(e.status!=='active')return;e.status='completed';e.finishedAt=finishedAt;e.result=result;e.expired=expired;for(const id of e.ids){const q=byId.get(id),attemptId=`${e.id}-${id}`;if(!s.attempts.some(a=>a.id===attemptId))s.attempts.push({id:attemptId,questionId:id,answerId:e.answers[id]??null,correct:e.answers[id]===q.correct_option_id,at:finishedAt,startedAt:e.startedAt,level:4,support:[],confidence:'sure',mistakes:[],taxonomy_version:1,sessionId:e.id,mode:e.timed===false?'practice':'exam'});}});examId=null;resultId=id;study=null;view='test';if(modal.open)modal.close();render();window.scrollTo(0,0);if(expired)toast('Time is up. Your saved answers have been submitted.');}
function resultsView(e){if(e.status==='abandoned')return `<div class="page-head"><div><p class="eyebrow">PAPER HISTORY</p><h1>This paper was abandoned.</h1><p>Its saved selections remain in history. It does not count as a pass or a completed mock.</p></div></div>${button('back-test','Back to Test','primary')}`;const p=profiles.find(p=>p.id===e.profileId),seconds=Math.max(0,Math.round((e.finishedAt-e.startedAt)/1000));return `<div class="page-head"><div><p class="eyebrow">${e.timed===false?'UNTIMED PRACTICE RESULT':'STRICT MOCK RESULT'} · LICENCE ${p.licence_category}</p><h1>${e.result.passed?'A solid step forward.':'You know what to revisit.'}</h1><p>This result is saved permanently. Reviewing below does not change it.</p></div>${button('back-test','Back to Test','ghost')}</div><section class="card"><div class="row between" style="flex-wrap:wrap"><div><div class="result-score">${e.result.correct}<small>/25</small></div><span class="tag ${e.result.passed?'':'critical'}">${e.result.passed?'PASSED':'NOT PASSED'}</span></div><div><p>${e.result.unanswered} unanswered · ${Math.floor(seconds/60)}m ${seconds%60}s used${e.expired?' · Time expired':''}</p><p class="muted">${e.result.criticalWrong?'A critical question was wrong or unanswered. This fails the paper regardless of the total.':`Critical question answered correctly. Licence ${p.licence_category} requires at least ${p.minimum_correct}/25.`}</p></div></div></section>${criticalResultRepair(e)}<div class="section-head"><h2>Understand every answer</h2></div>${e.ids.map((id,i)=>{const q=byId.get(id);return `<details><summary>${i+1}. Question ${q.official_id} · ${e.answers[id]===q.correct_option_id?'Correct':e.answers[id]?'Incorrect':'Unanswered'}${q.critical_for_motorcycle?' · Critical':''}</summary><div>${questionContent(q,{level:4,committed:true,examFinished:true,answerId:e.answers[id],reveals:new Set(['review']),confidence:'sure'})}</div></details>`;}).join('')}`;}
function settings(){openModal(`<p class="eyebrow">MAKE THIS SPACE YOURS</p><h2>Settings & backups</h2><div class="settings-grid"><div class="field"><label for="setting-level">Default English support</label><select id="setting-level">${levels.map((name,n)=>`<option value="${n}" ${state.preferences.level===n?'selected':''}>${n} · ${name}</option>`).join('')}</select></div><div class="field"><label for="setting-profile">Licence category</label><select id="setting-profile">${profiles.map(p=>`<option value="${p.id}" ${p.id===state.preferences.profileId?'selected':''}>${p.licence_category} · ${p.minimum_correct}/25 required</option>`).join('')}</select></div><div class="field"><label for="setting-limit">Daily new-question target</label><input id="setting-limit" type="number" min="1" max="250" value="${state.preferences.dailyLimit}"></div><div class="field"><label for="setting-theme">Appearance</label><select id="setting-theme">${['system','light','dark'].map(t=>`<option value="${t}" ${state.preferences.theme===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div></div><div class="actions">${button('save-settings','Save preferences','primary')}${closeButton()}</div><div class="divider"></div><h3>Your progress, your copy</h3><p class="muted">Progress belongs to this browser and device. Clearing browser storage removes it. Export regularly and import the file to continue elsewhere.</p><div class="actions">${button('export','Export JSON backup','secondary')}${button('choose-import','Import a backup','secondary')}${button('rollback','Restore before last import','ghost small')}</div><input id="backup-file" type="file" accept="application/json,.json" data-change="import-file" hidden><div class="divider"></div><h3>Offline practice</h3><p id="offline-settings-status">${escape(offlineLabel())}${offline.error?'<br>'+escape(offline.error):''}</p><p class="source-note">Offline readiness is shown only after the app, complete bank and all diagrams pass checksum verification. Keep this page open until preparation finishes.</p><div class="actions">${button('retry-offline','Retry offline preparation','secondary small')}${installPrompt?button('install','Install on this device','primary small'):''}</div>${registration?.waiting?'<div class="notice">An update is ready. Finish your paper and close all app tabs; the new version will activate safely on the next launch.</div>':''}<div class="divider"></div><p class="source-note">Bank: ${escape(bank.bank_id)} · Local schema 1<br>Profile verified through ${escape(profile().valid_through)} · Asia/Ho_Chi_Minh</p><div class="actions">${button('about','Content & source notes','ghost small')}${button('reset','Reset local progress','danger small')}</div>`);}
function about(){if(state.exams.some(e=>e.status==='active')){toast('Source notes are available after the whole paper ends.');return;}openModal(`<p class="eyebrow">FAITHFUL TO THE SOURCE</p><h2>The content behind your practice</h2><p>All <strong>250</strong> Vietnamese questions, <strong>790</strong> answer choices, <strong>20</strong> motorcycle-critical flags and <strong>128</strong> original source diagrams are bundled locally. Official question numbers retain their gaps from the 600-question book.</p><p>Vietnamese text, option order and keyed answers come from the supplied official-source audit. English questions, choices and teaching notes are AI-authored learning support and were reviewed for fidelity; they are <strong>not an official English translation</strong> or a guarantee of passing.</p><p>${escape(typeof bank.translation_notice==='string'?bank.translation_notice:'The original Vietnamese and official answer keys remain authoritative. Translations do not replace examination wording.')}</p><h3>Current-format boundary</h3><p>The supplied A/A1 profile has 25 questions, 19 minutes and exactly one critical question. A requires 23 correct, A1 requires 21; a wrong or unanswered critical answer fails. Valid through <strong>28 February 2027</strong>, using Vietnam-local dates. From 1 March 2027 this app keeps archived study available and disables current-format mocks until verified new content is installed.</p><h3>Source wording notes</h3>${[44,64,124,377,432].map(id=>byId.get('q'+String(id).padStart(3,'0'))).filter(Boolean).map(q=>`<p class="source-note"><strong>Question ${q.official_id}:</strong> ${escape(q.source_caution??'The official wording and answer are retained. Read qualifiers and enumeration carefully; the English support does not silently alter the source.')}</p>`).join('')}<h3>Sources for auditing</h3><ul>${bank.source_registry.map(s=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener">${escape(s.title)}</a>${s.publisher?' · '+escape(s.publisher):''}</li>`).join('')}</ul><p class="source-note">Official PDFs include underlined answer keys. They are available in post-answer review and this deliberate audit screen, never embedded into an active question.</p><div class="actions">${button('settings','Settings & backups','secondary')}${closeButton()}</div>`);}
function readinessModal(){const r=readiness(questions,state.attempts,state.exams);openModal(`<p class="eyebrow">PREPARATION, WITH EVIDENCE</p><h2>${r.ready&&profileValid(profile())?'Your practice evidence is strong.':'Build a reliable pattern.'}</h2><p>These preparation targets go beyond the legal pass mark. They are study recommendations and never guarantee a pass.</p>${!profileValid(profile())?'<div class="notice">The supplied profile has expired. Historical scores cannot establish current-format readiness.</div>':''}<ul class="ready-list">${[[r.coverage===250,`Attempt every question: ${r.coverage}/250`],[r.revisited===250,`Revisit each question on another day: ${r.revisited}/250`],[r.criticalMastered===20,`Independently secure all critical questions: ${r.criticalMastered}/20`],[r.lastTenStrong,`Last ten strict mixed mocks at 24–25/25, no critical errors: ${r.strongMocks}/10 strong`],[r.timeBuffer,'Finish at least eight of the last ten strict mocks within 16 minutes']].map(([done,label])=>`<li class="${done?'done':''}">${escape(label)}</li>`).join('')}</ul><p class="source-note">Independent mastery requires three confident, unaided correct responses on three Vietnam-local dates, with at least one three-day gap and no unresolved later error. Same-day repetition, guesses and English-assisted answers do not count.</p><div class="actions">${closeButton()}</div>`);}
function exportBackup(){const data={...structuredClone(state),exported_at:new Date().toISOString()},blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`duong-backup-${vnDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep the file somewhere safe.');}
async function previewImport(file){if(!file)return;if(state.exams.some(e=>e.status==='active'))throw Error('Finish or abandon your active paper before importing a backup. Your saved paper and timer are preserved.');if(file.size>25*1024*1024)throw Error('The backup is too large (maximum 25 MB).');const candidate=validateBackup(JSON.parse(await file.text()),bank.bank_id,new Set(byId.keys()),questions,profiles),activeExisting=state.exams.find(e=>e.status==='active'),activeIncoming=candidate.exams.find(e=>e.status==='active');if(activeExisting&&activeIncoming&&activeExisting.id!==activeIncoming.id)throw Error('Both this browser and the backup have different active papers. Finish or abandon the local paper before importing.');importCandidate=candidate;openModal(`<p class="eyebrow">BACKUP PREVIEW</p><h2>Review before importing</h2><p>This compatible backup contains ${candidate.attempts.length} answer attempts, ${candidate.exams.length} papers, ${candidate.phraseAttempts.length} phrase attempts and ${candidate.bookmarks.length} bookmarks.</p><p>Records merge by stable event IDs; existing attempt and result events are preserved. Preferences from the backup will apply. A rollback copy of your current data is saved before the merge.</p><div class="actions">${button('apply-import','Merge this backup','primary')}${button('settings','Cancel','secondary')}</div>`);}
async function applyImport(){if(!importCandidate)return;if(!storageReady)throw Error('Working browser storage is required before importing.');const merged=mergeBackups(state,importCandidate);validateBackup(merged,bank.bank_id,new Set(byId.keys()),questions,profiles);await saveRollback(state);await persist(merged);importCandidate=null;study=null;examId=null;resultId=null;modal.close();render();toast('Backup merged. Your previous state is available under Restore before last import.');}
async function registerOffline(){if(!('serviceWorker'in navigator)){offline.error='This browser does not support offline installation.';updateOfflineUI();return;}navigator.serviceWorker.addEventListener('message',event=>{const m=event.data;if(!m||typeof m.type!=='string')return;if(m.type==='OFFLINE_READY'&&(event.source===navigator.serviceWorker.controller||event.source===registration?.active||event.source?.state==='activated'))offline={ready:true,done:m.done??m.total??0,total:m.total??0,error:''};if(m.type==='OFFLINE_STATUS'){offline.ready=!!m.ready;if(m.total){offline.done=m.done;offline.total=m.total;}}if(m.type==='OFFLINE_PROGRESS'&&!offline.ready){offline.done=m.done;offline.total=m.total;}if(m.type==='OFFLINE_ERROR'&&!offline.ready)offline.error=m.message||'Preparation is incomplete.';updateOfflineUI();});navigator.serviceWorker.addEventListener('controllerchange',()=>checkOffline());try{registration=await navigator.serviceWorker.register('./sw.js');await checkOffline();registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='activated')checkOffline();if(worker.state==='installed'&&registration.waiting)toast('An update is ready. Finish your paper and close all app tabs to apply it safely.');});});}catch(error){offline.error=error.message;updateOfflineUI();}}
async function checkOffline(){const worker=navigator.serviceWorker.controller||registration?.active;if(!worker)return;const channel=new MessageChannel();channel.port1.onmessage=({data})=>{if(data.type==='OFFLINE_STATUS'){offline.ready=!!data.ready;offline.done=data.done??0;offline.total=data.total??0;updateOfflineUI();}};worker.postMessage({type:'CHECK_STATUS'},[channel.port2]);}
function updateOfflineUI(){const label=document.querySelector('#offline-label');if(label)label.textContent=offlineLabel();const settings=document.querySelector('#offline-settings-status');if(settings)settings.textContent=offlineLabel()+(offline.error?' · '+offline.error:'');}
async function retryOffline(){offline.error='';if(!registration)await registerOffline();if(!registration){toast('Offline installation is unavailable. Check this browser’s site permissions.');return;}try{await registration.update();const worker=registration.installing||registration.waiting||registration.active;worker?.postMessage({type:'RETRY_OFFLINE'});await checkOffline();toast('Offline preparation resumed. Keep the app open.');}catch(error){offline.error=error.message;updateOfflineUI();}}
async function handleAction(action,node){switch(action){case'nav':setView(node.dataset.view);break;case'browse':collection='all';chapter='all';search='';setView('learn');break;case'chapter':chapter=node.dataset.chapter;collection='all';setView('learn');break;case'critical':collection='critical';chapter='all';search='';if(modal.open)modal.close();setView('learn');break;case'critical-priority':{const c=criticalProgress(questions,state.attempts);collection='critical';chapter='all';search='';view='learn';if(modal.open)modal.close();startStudy(c.priorityIds,state.preferences.level,'critical-review');break;}case'critical-drill':{collection='critical';chapter='all';search='';view='learn';if(modal.open)modal.close();const ids=questions.filter(q=>q.critical_for_motorcycle).map(q=>q.id);for(let i=ids.length-1;i>0;i--){const value=crypto.getRandomValues(new Uint32Array(1))[0],j=value%(i+1);[ids[i],ids[j]]=[ids[j],ids[i]];}startStudy(ids,3,'critical-drill');break;}case'repair-critical':{collection='critical';chapter='all';search='';view='learn';resultId=null;startStudy([node.dataset.id],state.preferences.level,'critical-review');break;}case'collection':collection=node.dataset.value;if(collection==='critical'){chapter='all';search='';}render();break;case'review-filter':reviewFilter=node.dataset.value;render();break;case'daily-learn':dailyLearn();break;case'due-review':view='review';reviewFilter='due';collection='all';chapter='all';startStudy(filteredQuestions(true).map(q=>q.id),state.preferences.level,'review');if(!study)render();break;case'study-list':startStudy(filteredQuestions().map(q=>q.id));break;case'review-list':startStudy(filteredQuestions(true).map(q=>q.id),state.preferences.level,'review');break;case'single':if(activeExam())throw Error('Finish or abandon your active paper before starting study.');view='learn';startStudy([node.dataset.id],node.dataset.level===undefined?state.preferences.level:Number(node.dataset.level));if(modal.open)modal.close();break;case'selected-ids':openModal(`<h2>Choose official question numbers</h2><p class="muted">Use original IDs from the 600-question book, separated by commas or spaces. Example: 19, 36, 362.</p><div class="field"><label for="selected-question-ids">Official numbers</label><input id="selected-question-ids" inputmode="numeric" placeholder="19, 36, 362"></div><div class="actions">${button('start-selected','Study selected questions','primary')}${closeButton()}</div>`);break;case'start-selected':{const values=document.querySelector('#selected-question-ids').value.split(/[\s,;]+/).filter(Boolean),ids=[...new Set(values.map(x=>'q'+String(Number(x)).padStart(3,'0')))];if(!ids.length||ids.some(id=>!byId.has(id)))throw Error('Some numbers are not in the official 250-question motorcycle subset. Check the original question numbers.');modal.close();view='learn';startStudy(ids);break;}case'answer':{const id=node.dataset.id;if(study&&!study.committed){study.answerId=id;render();}else{const e=activeExam();if(e){if(e.timed!==false&&e.deadline<=now()){await finishExam(e.id,true);break;}const qId=e.ids[examIndex];if(byId.get(qId).content_error)throw Error('The source diagram is unavailable. Reload or restore offline content before answering.');if(!byId.get(qId).options.some(o=>o.id===id))return;await change(s=>s.exams.find(x=>x.id===e.id).answers[qId]=id);render();}}break;}case'confidence':if(study&&!study.committed){study.confidence=node.dataset.value;render();}break;case'commit':await commitStudy();break;case'next-study':if(!study?.committed)break;if(study.index+1>=study.ids.length){const count=study.ids.length,sessionId=study.sessionId,criticalDrill=study.mode==='critical-drill';study=null;render();if(criticalDrill)showCriticalDrillSummary(sessionId);else toast(`${count} questions practised. Come back later for spaced retrieval.`);}else{study.index++;study.level=study.mode==='critical-drill'?3:state.preferences.level;Object.assign(study,{answerId:null,committed:false,confidence:'sure',reveals:new Set(),support:[],startedAt:now(),attemptId:null});render();window.scrollTo(0,0);}break;case'end-study':study=null;render();break;case'bookmark':await change(s=>{const i=s.bookmarks.indexOf(node.dataset.id);if(i<0)s.bookmarks.push(node.dataset.id);else s.bookmarks.splice(i,1);});render();break;case'reveal':if(study&&!study.committed&&study.level===1){study.reveals.add(node.dataset.field);study.support.push({type:'english',field:node.dataset.field,at:now()});render();}break;case'review-english':if(study?.committed){study.reveals.add('review');render();}break;case'phrase-help':if(study&&!study.committed&&study.level===2){const p=byPhrase.get(node.dataset.id);if(!p||p.ambiguous_without_context||p.automatic_gloss_allowed===false)return;study.support.push({type:'phrase',phraseId:p.id,at:now()});openModal(`<p class="eyebrow">PHRASE HELP</p><h2 lang="vi">${escape(p.vi)}</h2><p>${escape(p.en)}</p><p class="muted">${escape(p.reading_note_en)}</p>${closeButton()}`);}break;case'change-support':if(study?.mode==='critical-drill')throw Error('Finish this Vietnamese-only drill before changing its support.');openModal(`<h2>Choose the next step</h2><p>Changing support starts this question again and records the new level. It does not change an earlier answer.</p><div class="field"><label for="next-support">English support</label><select id="next-support">${levels.map((name,i)=>`<option value="${i}" ${study.level===i?'selected':''}>${i} · ${name}</option>`).join('')}</select></div><div class="actions">${button('apply-support','Apply to a new attempt','primary')}${closeButton()}</div>`);break;case'apply-support':{if(study?.mode==='critical-drill')throw Error('Finish this Vietnamese-only drill before changing its support.');const level=Number(document.querySelector('#next-support').value);await change(s=>s.preferences.level=level);study.level=level;Object.assign(study,{answerId:null,committed:false,confidence:'sure',reveals:new Set(),support:[],startedAt:now(),attemptId:null});modal.close();render();break;}case'zoom':{const q=byId.get(node.dataset.id),im=q.images[Number(node.dataset.index)];openModal(`<h2 lang="vi">${escape(im.alt_vi)}</h2><div class="figures"><figure class="figure"><img src="${escape(im.path)}" alt="${escape(im.alt_vi)}" width="${im.width}" height="${im.height}">${im.figure_label?`<figcaption lang="vi">Hình ${escape(im.figure_label)}</figcaption>`:''}</figure></div><p class="source-note">Original source pixels and proportions. Use your device’s pinch zoom if needed.</p>${closeButton()}`);break;}case'phrases':if(state.exams.some(e=>e.status==='active'))throw Error('Finish or abandon the active paper before opening phrase help.');setupPhraseQueue();view='phrases';study=null;render();break;case'repair-phrases':{const q=byId.get(node.dataset.id);setupPhraseQueue(q.phrase_ids);study=null;view='phrases';render();break;}case'phrase-mode':phraseMode=node.dataset.value;resetPhrase();render();break;case'phrase-reveal':phraseRevealed=true;render();break;case'phrase-rate':await recordPhrase(node.dataset.value==='true');phraseIndex=(phraseIndex+1)%phraseQueue.length;resetPhrase();render();break;case'phrase-answer':if(phraseAnswer)break;phraseAnswer=node.dataset.id;await recordPhrase(phraseAnswer===phraseQueue[phraseIndex]);render();break;case'phrase-next':phraseIndex=(phraseIndex+1)%phraseQueue.length;resetPhrase();render();break;case'phrase-speak':{const voice=speechVoice();if(!voice)break;const utterance=new SpeechSynthesisUtterance(byPhrase.get(phraseQueue[phraseIndex]).vi);utterance.voice=voice;utterance.lang='vi-VN';speechSynthesis.cancel();speechSynthesis.speak(utterance);break;}case'start-exam':await startExam(true);break;case'start-practice':await startExam(false);break;case'resume-exam':examId=node.dataset.id;view='test';study=null;resultId=null;examIndex=0;render();break;case'exam-go':examIndex=Number(node.dataset.index);render();window.scrollTo(0,0);break;case'exam-prev':examIndex=Math.max(0,examIndex-1);render();window.scrollTo(0,0);break;case'exam-next':examIndex=Math.min(24,examIndex+1);render();window.scrollTo(0,0);break;case'submit-exam':{const e=activeExam();if(!e)break;const blanks=e.ids.filter(id=>!e.answers[id]).length;openModal(`<h2>Submit the whole paper?</h2><p>${blanks?`${blanks} questions are unanswered. Blank answers are marked incorrect.`:'All 25 questions have a selected answer.'} You can review translations and explanations after submission. This result cannot be changed.</p><div class="actions">${button('confirm-submit','Submit now','primary',`data-id="${e.id}"`)}${button('close-modal','Keep answering','secondary')}</div>`);break;}case'confirm-submit':await finishExam(node.dataset.id);break;case'abandon-exam':openModal(`<h2>Abandon this paper?</h2><p>The paper and its selections remain in history as abandoned. It will not count as a pass.</p><div class="actions">${button('confirm-abandon','Abandon paper','danger',`data-id="${node.dataset.id}"`)}${button('close-modal','Keep the paper','secondary')}</div>`);break;case'confirm-abandon':await change(s=>{const e=s.exams.find(x=>x.id===node.dataset.id);if(e?.status==='active'){e.status='abandoned';e.finishedAt=now();}});examId=null;resultId=null;modal.close();render();break;case'exam-result':resultId=node.dataset.id;examId=null;study=null;render();window.scrollTo(0,0);break;case'back-test':resultId=null;examId=null;view='test';render();break;case'settings':settings();break;case'about':about();break;case'readiness':readinessModal();break;case'close-modal':modal.close();break;case'save-settings':{const level=Number(document.querySelector('#setting-level').value),profileId=document.querySelector('#setting-profile').value,dailyLimit=Number(document.querySelector('#setting-limit').value),theme=document.querySelector('#setting-theme').value;if(!Number.isInteger(dailyLimit)||dailyLimit<1||dailyLimit>250)throw Error('Choose a daily target from 1 to 250.');const active=state.exams.find(e=>e.status==='active');if(active&&(level!==state.preferences.level||profileId!==state.preferences.profileId)&&!confirm('Changing support or licence category abandons the active mock. Continue?'))return;await change(s=>{if(active&&(level!==s.preferences.level||profileId!==s.preferences.profileId)){const e=s.exams.find(x=>x.id===active.id);e.status='abandoned';e.finishedAt=now();}s.preferences={level,profileId,dailyLimit,theme};});if(study&&study.level!==level)toast('New support preference applies from your next question.');if(active&&!state.exams.find(e=>e.id===active.id&&e.status==='active'))examId=null;modal.close();render();toast('Preferences saved.');break;}case'export':exportBackup();break;case'choose-import':document.querySelector('#backup-file').click();break;case'apply-import':await applyImport();break;case'rollback':{if(state.exams.some(e=>e.status==='active'))throw Error('Finish or abandon your active paper before restoring a backup. Your saved paper and timer are preserved.');const old=await readRollback();if(!old)throw Error('There is no pre-import snapshot to restore yet.');validateBackup(old,bank.bank_id,new Set(byId.keys()),questions,profiles);if(!confirm('Restore the exact progress saved before your last import? Current progress will be replaced. Export first if you want to keep it.'))return;await persist(old);study=null;examId=null;resultId=null;modal.close();render();toast('Pre-import progress restored.');break;}case'reset':openModal(`<h2>Reset all local progress?</h2><p>Export a backup first. Reset removes your attempts, papers, phrase history and saved questions from this browser.</p><div class="actions">${button('export','Export backup first','secondary')}${button('confirm-reset','Reset all progress','danger')}${button('settings','Cancel','ghost')}</div>`);break;case'confirm-reset':if(!confirm('Permanently reset all progress on this browser?'))return;await persist(fresh());study=null;examId=null;resultId=null;view='today';modal.close();render();toast('Local progress reset.');break;case'retry-offline':await retryOffline();break;case'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;settings();}break;}}
async function run(action,node){if(busy)return;busy=true;try{await handleAction(action,node);}catch(error){toast(error.message||String(error));console.error(error);if(storageError)render();}finally{busy=false;}}
document.addEventListener('click',event=>{const node=event.target.closest('[data-action]');if(!node)return;event.preventDefault();run(node.dataset.action,node);});
document.addEventListener('input',event=>{if(event.target.dataset.input==='search'){search=event.target.value;const position=event.target.selectionStart;render();const input=document.querySelector('#search');input?.focus();if(input&&position!==null)input.setSelectionRange(position,position);}});
document.addEventListener('change',async event=>{const node=event.target;if(!node.dataset.change)return;if(busy)return;busy=true;try{switch(node.dataset.change){case'chapter':chapter=node.value;render();break;case'mistake':mistakeFilter=node.value;render();break;case'support':await change(s=>s.preferences.level=Number(node.value));render();break;case'reason':{const attemptId=node.dataset.attempt,tags=[...document.querySelectorAll(`input[data-attempt="${attemptId}"]:checked`)].map(n=>n.value);await change(s=>s.mistakeEdits.push({id:uid(),attemptId,questionId:s.attempts.find(a=>a.id===attemptId).questionId,at:now(),mistakes:tags,taxonomy_version:1}));break;}case'import-file':await previewImport(node.files[0]);break;}}catch(error){toast(error.message);if(storageError)render();}finally{busy=false;}});
document.addEventListener('keydown',event=>{if(modal.open||event.ctrlKey||event.metaKey||event.altKey||event.target.closest('input,textarea,select,[contenteditable=true]'))return;if((event.key===' '||event.key==='Enter')&&event.target.matches('[role=button][data-action]')){event.preventDefault();event.target.click();return;}const q=study&&!study.committed?byId.get(study.ids[study.index]):activeExam()?byId.get(activeExam().ids[examIndex]):null;if(q&&/^[1-4]$/.test(event.key)){const o=q.options[Number(event.key)-1];if(o){event.preventDefault();run('answer',{dataset:{id:o.id}});}return;}if(event.key==='Enter'&&study&&!event.target.closest('button,a')){event.preventDefault();run(study.committed?'next-study':'commit',{dataset:{}});}if(activeExam()&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();run(event.key==='ArrowLeft'?'exam-prev':'exam-next',{dataset:{}});}});
document.addEventListener('error',event=>{const image=event.target;if(image instanceof HTMLImageElement&&image.dataset.questionImage){image.replaceWith(Object.assign(document.createElement('p'),{className:'error',textContent:'Source diagram unavailable. Do not answer this question without its original image. Retry offline preparation or reload when connected.'}));const q=byId.get(image.dataset.questionImage);if(q)q.content_error=true;}},true);
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('online',()=>{checkOffline();updateOfflineUI();});
window.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')tick();});
async function tick(){if(!state)return;updateTimer();const e=state.exams.find(e=>e.status==='active'&&e.timed!==false&&e.deadline<=now());if(e&&!busy){busy=true;try{await finishExam(e.id,true);}catch(error){storageError=error.message;toast(error.message);render();}finally{busy=false;}}}
async function boot(){try{const loaded=await Promise.all(['data/questions.json','data/phrases.json','data/exam_profiles.json'].map(async path=>{const r=await fetch(path);if(!r.ok)throw Error('Could not load '+path);return r.json();}));[bank,phraseData]=loaded;questions=bank.questions;phrases=phraseData.phrases;profiles=loaded[2].profiles;if(questions?.length!==250||new Set(questions.map(q=>q.id)).size!==250||phrases?.length!==93||!profiles?.length)throw Error('The bundled content is incomplete. Retry when connected.');byId=new Map(questions.map(q=>[q.id,q]));byPhrase=new Map(phrases.map(p=>[p.id,p]));state=fresh();try{await openStore();const saved=await readState();if(saved)state=validateBackup(saved,bank.bank_id,new Set(byId.keys()),questions,profiles);storageReady=true;if(!saved)await saveState(state);}catch(error){storageReady=false;storageError=error.message||'IndexedDB could not be opened.';}const e=state.exams.find(e=>e.status==='active');if(e){view='test';examId=e.id;if(e.timed!==false&&e.deadline<=now()&&storageReady)await finishExam(e.id,true);}render();registerOffline();setInterval(tick,1000);await tick();}catch(error){app.innerHTML=`<div class="boot error"><h1>Practice content could not load.</h1><p>${escape(error.message)}</p><p>Connect to the internet and reload. Your saved progress has not been reset.</p><button class="button primary" data-action="reload">Reload</button></div>`;document.querySelector('[data-action=reload]')?.addEventListener('click',()=>location.reload());}}
boot();
